SELECT * FROM plt_delivery_material WHERE tenant_id = #{query.tenantId} AND id IN
#{id}
AND deleted = b'0' ORDER BY id FOR UPDATE

SELECT * FROM plt_delivery_material
WHERE tenant_id=#{query.tenantId} AND deleted=b'0'
  AND ((owner_module=#{query.ownerModule} AND entity_id=#{query.entityId}
        AND (entity_type=#{query.entityType}
            OR entity_type='REQUIREMENT_ANALYSIS'))
    OR (source_owner_module=#{query.ownerModule} AND source_entity_id=#{query.entityId}
        AND (source_entity_type=#{query.entityType}
            OR source_entity_type='REQUIREMENT_ANALYSIS')))

  AND (type_code=#{query.typeCode} OR business_type_code=#{query.typeCode})

ORDER BY id DESC
